const pageInfo = { '/': ['Good morning, gold star team.', 'A calm view of today’s rhythm, rewards and follow-through.'], '/customers': ['Customers', 'Every relationship starts with a name, a phone number and a thoughtful next step.'], '/new-sale': ['New sale', 'A focused counter flow for fast, confident service.'], '/sales': ['Sales', 'Keep every bill, payment and reversal accountable.'], '/birthdays': ['Birthdays', 'Turn a date on the calendar into a warm reason to return.'], '/messages': ['Messages (legacy)', 'Birthday messaging now lives in the birthday care desk.'], '/legacy-import': ['Legacy import', 'Bring your showroom history forward without losing the story.'], '/reports': ['Reports', 'Read the business as a pattern, not just a number.'], '/settings': ['Settings', 'Tune the rules that make loyalty feel personal.'], '/staff': ['Staff', 'Make roles clear so the floor can move quickly.'], '/audit-log': ['Audit log', 'A transparent trail for every meaningful change.'], '/setup': ['Setup / health', 'A precise checklist for the connection between the app and Supabase.'] }

type ToastState = { message: string; tone: 'success' | 'error' } | null

function App() {
  const creds = getSupabaseCredentials()
  const [session, setSession] = useState<Session | null>(null)
  const [authLoading, setAuthLoading] = useState(creds.ready)
  const [profile, setProfile] = useState<StaffProfile | null>(null)
  const [profileLoading, setProfileLoading] = useState(false)
  const [toast, setToast] = useState<ToastState>(null)
  const [dark, setDark] = useState(() => localStorage.getItem('goldstar.dark') === 'true')
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('goldstar.dark', String(dark)) }, [dark])
  useEffect(() => { if (!supabase) { setAuthLoading(false); return }; let mounted = true; supabase.auth.getSession().then(({ data }) => { if (mounted) { setSession(data.session); setAuthLoading(false) } }); const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => { setSession(next); setAuthLoading(false) }); return () => { mounted = false; listener.subscription.unsubscribe() } }, [creds.ready])
  useEffect(() => { if (!session || !supabase) { setProfile(null); return }; setProfileLoading(true); supabase.from('staff_profiles').select('*').eq('id', session.user.id).maybeSingle().then(({ data }) => { setProfile(data as StaffProfile | null); setProfileLoading(false) }) }, [session])
  const signOut = async () => { await supabase?.auth.signOut(); setSession(null); setProfile(null) }
  if (!creds.ready) return <><ConnectPage onToast={setToast} /><Toast message={toast?.message || null} tone={toast?.tone} onClose={() => setToast(null)} /></>
  if (authLoading || profileLoading) return <LoadingScreen />
  if (!session) return <><LoginPage onToast={setToast} /><Toast message={toast?.message || null} tone={toast?.tone} onClose={() => setToast(null)} /></>
  if (!profile) return <><ProfileMissingPage onSignOut={signOut} /><Toast message={toast?.message || null} tone={toast?.tone} onClose={() => setToast(null)} /></>
  if (!profile.is_active) return <><InactivePage onSignOut={signOut} /><Toast message={toast?.message || null} tone={toast?.tone} onClose={() => setToast(null)} /></>
  return <AppShell role={profile.role} name={profile.full_name} onSignOut={signOut} onToggleDark={() => setDark(v => !v)}><Routes>
    <Route path="/" element={<DashboardPage profile={profile} onToast={setToast} />} />
    <Route path="/customers" element={<CustomersPage onToast={setToast} />} />
    <Route path="/customers/:id" element={<CustomerProfilePage role={profile.role} onToast={setToast} />} />
    <Route path="/new-sale" element={<NewSalePage profile={profile} onToast={setToast} />} />
    <Route path="/sales" element={<SalesPage role={profile.role} onToast={setToast} />} />
    <Route path="/sales/:id" element={<SaleDetailPage role={profile.role} onToast={setToast} />} />
    <Route path="/birthdays" element={isManager(profile.role) ? <BirthdaysPage onToast={setToast} /> : <Navigate to="/" replace />} />
    <Route path="/messages" element={isManager(profile.role) ? <MessagesPage onToast={setToast} /> : <Navigate to="/" replace />} />
    <Route path="/legacy-import" element={isManager(profile.role) ? <LegacyImportPage onToast={setToast} /> : <Navigate to="/" replace />} />
    <Route path="/reports" element={isManager(profile.role) ? <ReportsPage /> : <Navigate to="/" replace />} />
    <Route path="/settings" element={isAdmin(profile.role) ? <SettingsPage onToast={setToast} /> : <Navigate to="/" replace />} />
    <Route path="/staff" element={isAdmin(profile.role) ? <StaffPage onToast={setToast} /> : <Navigate to="/" replace />} />
    <Route path="/audit-log" element={isAdmin(profile.role) ? <AuditPage /> : <Navigate to="/" replace />} />
    <Route path="/setup" element={isAdmin(profile.role) ? <SetupPage /> : <Navigate to="/" replace />} />
    <Route path="*" element={<Navigate to="/" replace />} />
  </Routes></AppShell>
}

function LoadingScreen() { return <div className="grid min-h-screen place-items-center bg-paper p-6 dark:bg-[#000000]"><div className="flex flex-col items-center gap-4"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-ink text-gold shadow-gold"><Sparkles size={24} fill="currentColor" className="animate-pulse" /></div><p className="text-sm text-graphite">Preparing your showroom…</p></div></div> }

function ConnectPage({ onToast }: { onToast: (state: ToastState) => void }) {
  const [url, setUrl] = useState(''); const [key, setKey] = useState(''); const [testing, setTesting] = useState(false); const [tested, setTested] = useState(false); const [error, setError] = useState('')
  const test = async () => { setTesting(true); setError(''); setTested(false); try { if (!url || !key) throw new Error('Add both your Supabase Project URL and publishable/anon key.'); const client = createClient(url.trim(), key.trim()); const { error: connectionError } = await client.from('showrooms').select('id', { head: true, count: 'exact' }).limit(1); if (connectionError && connectionError.code !== 'PGRST116') throw connectionError; setTested(true); onToast({ message: 'Connection looks good. Save to continue.', tone: 'success' }) } catch (e) { setError(safeError(e)) } finally { setTesting(false) } }
  const save = () => { if (!tested) { setError('Test the connection before saving.'); return }; saveSupabaseCredentials(url, key); window.location.reload() }
  return <div className="min-h-screen bg-[#000000] px-4 py-10 text-white sm:px-8"><div className="mx-auto flex min-h-[calc(100vh-5rem)] max-w-6xl items-center"><div className="grid w-full overflow-hidden rounded-[2rem] bg-paper text-ink shadow-soft lg:grid-cols-[.9fr_1.1fr]"><div className="relative overflow-hidden bg-ink p-8 text-white sm:p-12"><div className="absolute -right-24 -top-24 h-72 w-72 rounded-full border border-gold/20" /><div className="absolute -bottom-32 -left-20 h-72 w-72 rounded-full border border-gold/10" /><div className="relative flex h-full flex-col justify-between"><div><div className="mb-8 flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-gold text-ink"><Sparkles size={22} fill="currentColor" /></span><div><p className="font-display text-xl">Goldstar</p><p className="text-[10px] uppercase tracking-[.2em] text-white/45">Banepa loyalty</p></div></div><p className="mb-4 text-[11px] font-bold uppercase tracking-[.18em] text-gold">A connected showroom</p><h1 className="max-w-md font-display text-4xl leading-[1.08] sm:text-5xl">Your customer story, ready at the counter.</h1><p className="mt-6 max-w-md text-sm leading-7 text-white/60">Connect the Supabase project that already holds your showroom data. Goldstar never creates schema or sample records.</p></div><div className="mt-16 flex items-center gap-3 text-xs text-white/45"><ShieldCheck size={16} className="text-gold" /> Browser-safe publishable key only</div></div></div><div className="p-8 sm:p-12"><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-gold">First connection</p><h2 className="font-display text-3xl">Connect your database</h2><p className="mt-3 text-sm leading-6 text-graphite">Use the Project URL and publishable/anon key from Supabase Project Settings → API.</p><div className="mt-8 space-y-5"><Field label="Project URL"><input className={inputClass} value={url} onChange={e => setUrl(e.target.value)} placeholder="https://your-project.supabase.co" /></Field><Field label="Publishable / anon key"><textarea className={cls(textareaClass, 'min-h-24 resize-none font-mono text-xs')} value={key} onChange={e => setKey(e.target.value)} placeholder="eyJhbGciOiJIUzI1NiIs…" /></Field>{error && <div className="rounded-xl bg-white p-3 text-sm text-black"><AlertCircle size={16} className="mr-2 inline" />{error}</div>}<div className="flex flex-col gap-3 sm:flex-row"><Button variant="outline" className="flex-1" loading={testing} onClick={test}>Test connection</Button><Button variant="secondary" className="flex-1" disabled={!tested} onClick={save}>Save and reload <ArrowRight size={16} /></Button></div><p className="text-center text-xs text-graphite">Only browser-safe credentials are accepted here.</p></div></div></div></div></div>
}

function LoginPage({ onToast }: { onToast: (state: ToastState) => void }) { const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const submit = async (e: React.FormEvent) => { e.preventDefault(); setLoading(true); setError(''); try { const { error: authError } = await requireSupabase().auth.signInWithPassword({ email, password }); if (authError) throw authError } catch (e) { setError(safeError(e)); onToast({ message: safeError(e), tone: 'error' }) } finally { setLoading(false) } }; return <div className="grid min-h-screen place-items-center bg-paper px-4 py-10 dark:bg-[#000000]"><div className="w-full max-w-md"><div className="mb-8 text-center"><div className="mx-auto mb-5 grid h-14 w-14 place-items-center rounded-2xl bg-ink text-gold shadow-gold"><Sparkles size={25} fill="currentColor" /></div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-gold">Goldstar Banepa</p><h1 className="font-display text-4xl">Sign in to your showroom</h1><p className="mt-3 text-sm text-graphite">A quiet, confident start to every customer conversation.</p></div><Panel><form onSubmit={submit} className="space-y-5"><Field label="Email"><input className={inputClass} type="email" value={email} onChange={e => setEmail(e.target.value)} autoComplete="email" required /></Field><Field label="Password"><input className={inputClass} type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required /></Field>{error && <div className="rounded-xl bg-white p-3 text-sm text-black"><AlertCircle size={16} className="mr-2 inline" />{error}</div>}<Button className="w-full" size="lg" loading={loading}>Sign in <ArrowRight size={17} /></Button></form></Panel><p className="mt-6 text-center text-xs text-graphite">Access is managed by your showroom administrator.</p></div></div> }
function ProfileMissingPage({ onSignOut }: { onSignOut: () => void }) { return <div className="grid min-h-screen place-items-center bg-paper px-4 dark:bg-[#000000]"><div className="max-w-md text-center"><div className="mx-auto mb-6 grid h-16 w-16 place-items-center rounded-3xl bg-gold/15 text-gold"><ShieldCheck size={28} /></div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-gold">Staff profile required</p><h1 className="font-display text-4xl">Your profile is not ready yet.</h1><p className="mt-4 text-sm leading-6 text-graphite">Ask an administrator to add your user to staff_profiles. Once your role is assigned, you can sign in here.</p><Button className="mt-7" variant="outline" onClick={onSignOut}><LogOutIcon /> Sign out</Button></div></div> }
function InactivePage({ onSignOut }: { onSignOut: () => void }) { return <div className="grid min-h-screen place-items-center bg-paper px-4 dark:bg-[#000000]"><div className="max-w-md text-center"><div className="mx-auto mb-6 grid h-16 w-16 place-items-center rounded-3xl bg-gold/15 text-gold"><LockKeyhole size={28} /></div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-gold">Pending approval</p><h1 className="font-display text-4xl">Waiting for admin approval.</h1><p className="mt-4 text-sm leading-6 text-graphite">Your showroom profile exists, but it is currently inactive. An administrator can activate it from Staff.</p><Button className="mt-7" variant="outline" onClick={onSignOut}><LogOutIcon /> Sign out</Button></div></div> }
function LogOutIcon() { return <LogOut size={16} /> }

function PageFrame({ children }: { children: React.ReactNode }) { return <div className="animate-[fadeIn_.35s_ease-out]">{children}</div> }

function DashboardPage({ onToast }: { profile: StaffProfile; onToast: (state: ToastState) => void }) {
  const today = todayKathmandu()
  const focus = useQuery({ queryKey: ['loyalty-dashboard', today], queryFn: async () => {
    if (!supabase) return { rewards: [], coupons: [], messages: [], redemptions: [], birthdays: [] }
    const [rewards, coupons, messages, redemptions, birthdays] = await Promise.all([
      supabase.from('customer_overview').select('*').eq('reward_ready', true).limit(10),
      supabase.from('birthday_coupons').select('id,status,discount_pct,valid_on').gte('valid_on', today),
      supabase.from('message_log').select('id,status'),
      supabase.from('loyalty_redemptions').select('id,method,discount_pct,status').eq('status', 'applied'),
      supabase.from('customers').select('id,full_name,phone,date_of_birth,sms_consent').not('date_of_birth', 'is', null).eq('is_active', true).limit(100)
    ])
    return { rewards: rewards.data || [], coupons: coupons.data || [], messages: messages.data || [], redemptions: redemptions.data || [], birthdays: birthdays.data || [] }
  }, enabled: Boolean(supabase) })
  const data = focus.data || { rewards: [], coupons: [], messages: [], redemptions: [], birthdays: [] }
  const queued = data.messages.filter((message: { status: string }) => message.status === 'queued').length
  const failed = data.messages.filter((message: { status: string }) => message.status === 'failed').length
  const issued = data.coupons.filter((coupon: { status: string }) => coupon.status === 'issued').length
  return <PageFrame><SectionHeading eyebrow={new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Kathmandu', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date())} title="Every pair brings you closer." description="A loyalty-first view of the customers, birthday rewards, and discount moments that deserve attention today." action={<Button size="lg" variant="secondary" onClick={() => window.location.href = '/birthdays'}><Cake size={18} /> Open birthday desk</Button>} /><div className="mb-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Rewards ready" value={String(data.rewards.length)} helper="Customers one pair away from a conversation" icon={Gift} /><StatCard label="Coupons in play" value={String(issued)} helper="Issued birthday rewards from today onward" icon={Ticket} /><StatCard label="Messages queued" value={String(queued)} helper={failed ? `${failed} failed delivery needs care` : 'No failed delivery alerts'} icon={MessageCircle} /><StatCard label="Discount redemptions" value={String(data.redemptions.length)} helper="Database-confirmed loyalty rewards" icon={Tag} /></div><div className="grid gap-6 xl:grid-cols-[1.25fr_.75fr]"><Panel eyebrow="Loyalty care queue" title="Customers ready for the next reward" action={<Badge tone="gold">Live from DB</Badge>}>{focus.isLoading ? <SkeletonRows /> : data.rewards.length ? <div className="divide-y divide-line">{data.rewards.map((customer: CustomerOverview) => <a href={`/customers/${customer.id}`} key={customer.id} className="flex items-center gap-3 py-4 first:pt-0 last:pb-0"><div className="grid h-10 w-10 place-items-center rounded-full bg-gold/15 font-display text-gold">{customer.full_name.slice(0, 1)}</div><div className="min-w-0 flex-1"><p className="truncate font-semibold">{customer.full_name}</p><p className="text-xs text-graphite">{customer.phone} · {customer.progress_in_cycle}/{customer.cycle_size} pairs</p></div><Badge tone="gold">Reward ready</Badge><ArrowRight size={16} className="text-graphite" /></a>)}</div> : <EmptyState icon={Gift} title="The next reward is waiting to be earned" description="When a customer reaches their reward milestone, they will appear here for a thoughtful follow-up." action={<Button variant="outline" onClick={() => window.location.href='/customers'}>Explore customers</Button>} />}</Panel><Panel eyebrow="Discount desk" title="Keep the warm moments moving"><div className="space-y-3"><QuickAction icon={Cake} label="Birthdays & messages" detail="Generate, edit, and send birthday rewards" onClick={() => window.location.href='/birthdays'} /><QuickAction icon={QrCode} label="Redeem a QR coupon" detail="Scan a digital coupon at the counter" onClick={() => window.location.href='/new-sale'} /><QuickAction icon={Users} label="Review stamp cards" detail="Find progress by name or phone" onClick={() => window.location.href='/customers'} /></div><div className="mt-6 rounded-2xl bg-ink p-4 text-paper"><div className="mb-3 flex items-center gap-2 text-gold"><Sparkles size={15} /><span className="text-xs font-bold uppercase tracking-[.12em]">Counter note</span></div><p className="font-display text-lg leading-6">The sale is the moment. Loyalty is the reason they return.</p></div></Panel></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><Panel eyebrow="Birthday radar" title="Upcoming customers"><div className="divide-y divide-line">{data.birthdays.slice(0, 5).map((customer: any) => <button key={customer.id} onClick={() => window.location.href='/birthdays'} className="flex w-full items-center gap-3 py-3 text-left"><div className="grid h-9 w-9 place-items-center rounded-full bg-gold/15 text-gold"><Cake size={16} /></div><div className="flex-1"><p className="font-semibold">{customer.full_name}</p><p className="text-xs text-graphite">{customer.phone} · {formatDate(customer.date_of_birth)}</p></div><MessageCircle size={16} className="text-graphite" /></button>)}{!data.birthdays.length && <EmptyState icon={Cake} title="No upcoming birthdays" description="Birthday customers will appear here once the connected database has dates." />}</div></Panel><Panel eyebrow="Next action" title="Make the discount feel personal"><p className="text-sm leading-6 text-graphite">Open a birthday customer, tune the message in their portal, then let the database issue the coupon and the counter redeem it by QR.</p><Button className="mt-5" variant="secondary" onClick={() => window.location.href='/birthdays'}><Send size={16} /> Go to birthday desk</Button></Panel></div></PageFrame>
}

function StatCard({ label, value, helper, icon: Icon }: { label: string; value: string; helper: string; icon: typeof CircleDollarSign }) { return <div className="surface rounded-2xl border border-line bg-white/80 p-5 shadow-soft dark:bg-[#000000]"><div className="mb-7 flex items-center justify-between"><p className="text-xs font-semibold uppercase tracking-[.09em] text-graphite">{label}</p><div className="grid h-9 w-9 place-items-center rounded-xl bg-gold/15 text-gold"><Icon size={18} /></div></div><p className="font-display text-3xl">{value}</p><p className="mt-2 text-xs text-graphite">{helper}</p></div> }
function MiniMetric({ icon: Icon, label, value }: { icon: LucideIcon; label: string; value: string }) { return <div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-sand text-ink"><Icon size={16} /></div><span className="flex-1 text-sm text-graphite">{label}</span><span className="font-semibold">{value}</span></div> }
function QuickAction({ icon: Icon, label, detail, onClick }: { icon: LucideIcon; label: string; detail: string; onClick: () => void }) { return <button onClick={onClick} className="group flex items-center gap-3 rounded-2xl border border-line p-4 text-left transition hover:border-gold hover:shadow-gold"><span className="grid h-10 w-10 place-items-center rounded-xl bg-ink text-gold"><Icon size={17} /></span><span className="flex-1"><span className="block text-sm font-semibold">{label}</span><span className="block text-xs text-graphite">{detail}</span></span><ChevronRight size={16} className="text-graphite transition group-hover:translate-x-1" /></button> }

const customerSchema = z.object({ full_name: z.string().min(2, 'Name is required'), phone: z.string().refine(isValidNepaliPhone, 'Use a 10-digit Nepali mobile starting with 9'), date_of_birth: z.string().min(1, 'Birthday day and month are required'), dob_year_unknown: z.boolean().default(false), email: z.string().email('Enter a valid email').optional().or(z.literal('')), address: z.string().optional(), sms_consent: z.boolean().default(true) })
type CustomerForm = z.infer<typeof customerSchema>

function CustomersPage({ onToast }: { onToast: (state: ToastState) => void }) { const location = useLocation(); const params = new URLSearchParams(location.search); const [search, setSearch] = useState(params.get('search') || ''); const [filter, setFilter] = useState('all'); const [open, setOpen] = useState(false); const [page, setPage] = useState(0); const customers = useQuery({ queryKey: ['customers', search, filter, page], queryFn: async () => { if (!supabase) return [] as CustomerOverview[]; if (search.trim()) { const { data, error } = await supabase.rpc('search_customers', { p_query: search.trim(), p_limit: 25 }); if (error) throw error; return (data || []) as CustomerOverview[] } let query = supabase.from('customer_overview').select('*').order('full_name').range(page * 25, page * 25 + 24); if (filter === 'reward') query = query.eq('reward_ready', true); if (filter === 'coupon') query = query.not('active_coupon_code', 'is', null); const { data, error } = await query; if (error) throw error; return (data || []) as CustomerOverview[] }, enabled: Boolean(supabase) }); const rows = customers.data || []; const exportRows = rows.map(c => ({ Name: c.full_name, Phone: c.phone, Pairs: `${c.progress_in_cycle}/${c.cycle_size}`, LifetimeSpend: c.lifetime_spend, Visits: c.visit_count, RewardReady: c.reward_ready ? 'Yes' : 'No' })); return <PageFrame><SectionHeading eyebrow="Customer care" title={pageInfo['/customers'][0]} description={pageInfo['/customers'][1]} action={<Button variant="secondary" onClick={() => setOpen(true)}><UserPlus size={17} /> Add customer</Button>} /><div className="mb-5 flex flex-col gap-3 lg:flex-row lg:items-center"><div className="flex flex-1 items-center gap-2 rounded-xl border border-line bg-white px-3 dark:bg-[#000000]"><Search size={17} className="text-graphite" /><input value={search} onChange={e => { setSearch(e.target.value); setPage(0) }} placeholder="Search by phone or name…" className="h-11 flex-1 bg-transparent text-sm outline-none placeholder:text-graphite" /><kbd className="rounded bg-sand px-1.5 py-0.5 text-[10px] text-graphite">250ms</kbd></div><div className="flex gap-2 overflow-x-auto">{[['all','All'],['reward','Reward ready'],['coupon','Coupon available'],['birthday','Birthday this month']].map(([key,label]) => <button key={key} onClick={() => setFilter(key)} className={cls('whitespace-nowrap rounded-xl px-3 py-2 text-xs font-semibold', filter === key ? 'bg-ink text-paper' : 'border border-line text-graphite')}>{label}</button>)}<Button variant="outline" size="sm" onClick={() => csvDownload('goldstar-customers.csv', exportRows)}><Download size={14} /> CSV</Button></div></div><Panel title="Customer directory" action={<span className="text-xs text-graphite">Page {page + 1} · 25 per page</span>}>{customers.isLoading ? <SkeletonRows count={6} /> : customers.error ? <InlineError message={safeError(customers.error)} /> : rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.12em] text-graphite"><th className="pb-3">Customer</th><th className="pb-3">Progress</th><th className="pb-3">Lifetime spend</th><th className="pb-3">Last visit</th><th className="pb-3">Status</th><th className="pb-3"></th></tr></thead><tbody className="divide-y divide-line">{rows.map(customer => <tr key={customer.id} className="group"><td className="py-4"><a href={`/customers/${customer.id}`} className="flex items-center gap-3"><span className="grid h-9 w-9 place-items-center rounded-full bg-sand font-display text-ink">{customer.full_name.slice(0,1)}</span><span><span className="block font-semibold group-hover:text-gold">{customer.full_name}</span><span className="block text-xs text-graphite">{customer.phone}</span></span></a></td><td className="py-4"><div className="flex gap-1">{Array.from({ length: Math.min(customer.cycle_size || 10, 10) }).map((_, i) => <span key={i} className={cls('h-2.5 w-2.5 rounded-full border', i < customer.progress_in_cycle ? 'border-gold bg-gold' : 'border-line')} />)}</div><span className="mt-1 block text-xs text-graphite">{customer.progress_in_cycle}/{customer.cycle_size}</span></td><td className="py-4 text-sm font-semibold">{formatCurrency(customer.lifetime_spend)}</td><td className="py-4 text-sm text-graphite">{formatDate(customer.last_purchase_at)}</td><td className="py-4"><div className="flex flex-wrap gap-1.5">{customer.reward_ready && <Badge tone="gold">Reward ready</Badge>}{customer.active_coupon_code && <Badge tone="green">Coupon</Badge>}</div></td><td className="py-4 text-right"><a href={`/customers/${customer.id}`} className="text-graphite hover:text-ink"><ChevronRight size={17} /></a></td></tr>)}</tbody></table></div> : <EmptyState icon={Users} title="Your directory is ready for its first customer" description="No records are shown until you connect your existing database and add a customer." action={<Button variant="outline" onClick={() => setOpen(true)}><UserPlus size={16} /> Add the first customer</Button>} />}<div className="mt-5 flex justify-end gap-2"><Button size="sm" variant="outline" disabled={page === 0} onClick={() => setPage(p => p - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={rows.length < 25} onClick={() => setPage(p => p + 1)}>Next</Button></div></Panel>{open && <AddCustomerDialog onClose={() => setOpen(false)} onToast={onToast} />}</PageFrame> }

function AddCustomerDialog({ onClose, onToast }: { onClose: () => void; onToast: (state: ToastState) => void }) { const { register, handleSubmit, formState: { errors, isSubmitting }, watch, setValue } = useForm<CustomerForm>({ resolver: zodResolver(customerSchema), defaultValues: { sms_consent: true, dob_year_unknown: false } }); const unknown = watch('dob_year_unknown'); const submit = async (values: CustomerForm) => { try { if (!supabase) throw new Error('Connect your Supabase database to add customers.'); const { error } = await supabase.from('customers').insert({ full_name: values.full_name.trim(), phone: normalizePhone(values.phone), date_of_birth: values.date_of_birth, dob_year_unknown: values.dob_year_unknown, email: values.email || null, address: values.address || null, sms_consent: values.sms_consent, source: 'showroom', is_active: true }); if (error) { if (error.code === '23505') throw new Error('Customer already exists'); throw error }; onToast({ message: 'Customer added successfully.', tone: 'success' }); onClose() } catch (e) { onToast({ message: safeError(e), tone: 'error' }) } }; return <Dialog title="Add customer" onClose={onClose}><form onSubmit={handleSubmit(submit)} className="space-y-4"><Field label="Full name" error={errors.full_name?.message}><input className={inputClass} {...register('full_name')} placeholder="e.g. Sushma Shrestha" /></Field><Field label="Nepali mobile" error={errors.phone?.message}><input className={inputClass} {...register('phone')} placeholder="98XXXXXXXX" /></Field><Field label="Birthday (day and month)" error={errors.date_of_birth?.message}><input className={inputClass} type="date" {...register('date_of_birth')} /></Field><label className="flex items-start gap-3 rounded-xl bg-sand/60 p-3 text-sm"><input type="checkbox" className="mt-1 accent-[#0E4C92]" {...register('dob_year_unknown')} onChange={e => { setValue('dob_year_unknown', e.target.checked); }} /><span><span className="block font-semibold">I prefer not to share the year</span><span className="text-xs text-graphite">The database will store the year as 2000 and retain the day/month.</span></span></label><Field label="Email"><input className={inputClass} type="email" {...register('email')} placeholder="Optional" /></Field><Field label="Address"><textarea className={textareaClass} {...register('address')} rows={2} placeholder="Optional" /></Field><label className="flex items-center gap-2 text-sm"><input type="checkbox" className="accent-[#0E4C92]" {...register('sms_consent')} /> SMS consent (on by default)</label><div className="flex justify-end gap-2 pt-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" variant="secondary" loading={isSubmitting}>Save customer</Button></div></form></Dialog> }

function Dialog({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-ink/50 p-4 backdrop-blur-sm"><div className="max-h-[90vh] w-full max-w-lg overflow-auto rounded-2xl bg-paper p-6 shadow-soft dark:bg-[#000000]"><div className="mb-5 flex items-center justify-between"><h2 className="font-display text-2xl">{title}</h2><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-xl hover:bg-sand"><X size={18} /></button></div>{children}</div></div> }
function InlineError({ message }: { message: string }) { return <div className="rounded-xl bg-white p-4 text-sm text-black"><AlertCircle size={16} className="mr-2 inline" />{message}</div> }

function CustomerProfilePage({ role, onToast }: { role: Role; onToast: (state: ToastState) => void }) { const { id } = useParamsSafe(); const customer = useQuery({ queryKey: ['customer', id], queryFn: async () => { if (!supabase) return null; const { data, error } = await supabase.from('customer_overview').select('*').eq('id', id).maybeSingle(); if (error) throw error; return data as CustomerOverview | null }, enabled: Boolean(id && supabase) }); const [tab, setTab] = useState('Purchases'); const [adjustOpen, setAdjustOpen] = useState(false); if (customer.isLoading) return <SkeletonRows count={6} />; if (customer.error) return <InlineError message={safeError(customer.error)} />; const c = customer.data; if (!c) return <EmptyState icon={Users} title="Customer not found" description="The record may have been deactivated or is not visible to your role." />; const cycleSize = Math.max(1, Number(c.cycle_size) || 10); const progress = Math.min(cycleSize, Math.max(0, Number(c.progress_in_cycle) || 0)); const completedCycles = Math.max(0, Number(c.completed_cycles) || 0); const pairsUntilReward = Math.max(0, Number(c.pairs_until_reward) || 0); const totalPairs = Math.max(0, Number(c.total_pairs) || 0); return <PageFrame><a href="/customers" className="mb-5 inline-flex items-center gap-2 text-sm text-graphite hover:text-ink">← Back to customers</a><SectionHeading eyebrow="Customer profile" title={c.full_name} description={`${c.phone} · ${c.source.replace('_', ' ')}`} action={<div className="flex gap-2"><Button className="!border-white/50 !text-paper hover:!border-gold" variant="outline" size="sm"><Pencil size={14} /> Edit</Button>{isManager(role) && <Button variant="secondary" size="sm" onClick={() => setAdjustOpen(true)}><Plus size={14} /> Adjust pairs</Button>}</div>} /><div className="grid gap-6 xl:grid-cols-[1fr_.72fr]"><Panel className="!overflow-hidden !bg-ink !text-paper" eyebrow="Loyalty stamp card" title={`${completedCycles} completed cycle${completedCycles === 1 ? '' : 's'}`}><div className="mt-6 grid grid-cols-5 gap-3 sm:grid-cols-10">{Array.from({ length: cycleSize }).map((_, index) => <div key={index} className={cls('aspect-square rounded-full border-2 p-1.5', index < progress ? 'stamp-glow border-gold bg-gold text-ink' : 'border-white/35 bg-white/10')}><div className="grid h-full place-items-center rounded-full text-xs font-bold">{index < progress ? <Check size={14} /> : index + 1}</div></div>)}</div><div className="mt-7 flex items-end justify-between gap-4"><div><p className="text-3xl font-display">{c.reward_ready ? 'NEXT PAIR = REWARD' : `${pairsUntilReward} pairs to go`}</p><p className="mt-2 text-sm text-white/70">Database-owned progress · {totalPairs} total pairs</p></div><Sparkles className="text-gold" size={30} /></div></Panel><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-1"><MetricCard label="Lifetime spend" value={formatCurrency(c.lifetime_spend)} icon={WalletCards} /><MetricCard label="Visits" value={String(c.visit_count)} icon={ShoppingBag} /><MetricCard label="Birthday coupon" value={c.active_coupon_code || 'None active'} icon={Cake} helper={c.active_coupon_pct ? `${c.active_coupon_pct}% · valid ${formatDate(c.active_coupon_valid_on)}` : 'No offer available'} /></div></div><CustomerActivityTabs customerId={c.id} completedCycles={completedCycles} tab={tab} onTabChange={setTab} />{adjustOpen && <AdjustPairsDialog customer={c} onClose={() => setAdjustOpen(false)} onSaved={() => customer.refetch()} onToast={onToast} />}</PageFrame> }
function CustomerActivityTabs({ customerId, completedCycles, tab, onTabChange }: { customerId: string; completedCycles: number; tab: string; onTabChange: (tab: string) => void }) {
  const activity = useQuery({ queryKey: ['customer-activity', customerId], queryFn: async () => {
    if (!supabase) return { purchases: [], coupons: [], redemptions: [], messages: [] }
    const [purchases, coupons, redemptions, messages] = await Promise.all([
      supabase.from('sales').select('id,invoice_no,sale_date,total_amount,discount_type,status,payment_method').eq('customer_id', customerId).order('sale_date', { ascending: false }),
      supabase.from('birthday_coupons').select('id,coupon_code,discount_pct,issued_on,valid_on,status,redeemed_at,redeemed_sale_id').eq('customer_id', customerId).order('issued_on', { ascending: false }),
      supabase.from('loyalty_redemptions').select('id,sale_id,method,discount_pct,status,created_at').eq('customer_id', customerId).order('created_at', { ascending: false }),
      supabase.from('message_log').select('id,body,status,channel,created_at,sent_at,related_coupon_id').eq('customer_id', customerId).order('created_at', { ascending: false }),
    ])
    const firstError = [purchases, coupons, redemptions, messages].find(result => result.error)?.error
    if (firstError) throw firstError
    return { purchases: purchases.data || [], coupons: coupons.data || [], redemptions: redemptions.data || [], messages: messages.data || [] }
  }, enabled: Boolean(supabase && customerId) })
  const tabs = ['Purchases', 'Coupons & redemptions', 'Messages']
  const redemptionTone = (status: string) => status === 'applied' || status === 'redeemed' || status === 'sent' ? 'green' : status === 'failed' || status === 'expired' || status === 'cancelled' ? 'red' : 'neutral'
  return <div className="mt-6"><div className="mb-4 flex gap-2 overflow-x-auto border-b border-line">{tabs.map(item => <button key={item} onClick={() => onTabChange(item)} className={cls('border-b-2 px-3 pb-3 text-sm font-semibold whitespace-nowrap', tab === item ? 'border-gold text-ink dark:text-paper' : 'border-transparent text-graphite')}>{item}</button>)}</div>{activity.isLoading ? <Panel title={tab}><SkeletonRows count={4} /></Panel> : activity.error ? <InlineError message={safeError(activity.error)} /> : tab === 'Purchases' ? <Panel title="Purchases">{activity.data?.purchases.length ? <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.12em] text-graphite"><th className="pb-3">Invoice</th><th className="pb-3">Date</th><th className="pb-3">Total</th><th className="pb-3">Discount</th><th className="pb-3">Status</th></tr></thead><tbody className="divide-y divide-line">{activity.data.purchases.map((purchase: any) => <tr key={purchase.id}><td className="py-4 font-semibold">{purchase.invoice_no || purchase.id.slice(0, 8)}</td><td className="py-4 text-graphite">{formatDateTime(purchase.sale_date)}</td><td className="py-4 font-semibold">{formatCurrency(purchase.total_amount)}</td><td className="py-4 text-graphite capitalize">{String(purchase.discount_type || 'none').replace('_', ' ')}</td><td className="py-4"><Badge tone={redemptionTone(purchase.status)}>{purchase.status}</Badge></td></tr>)}</tbody></table></div> : <EmptyState icon={ShoppingBag} title="No purchases yet" description="Completed customer purchases will appear here." />}</Panel> : tab === 'Coupons & redemptions' ? <Panel title="Coupons & redemptions" eyebrow="Birthday coupons and loyalty rewards">{completedCycles > (activity.data?.redemptions.filter((item: any) => item.status === 'applied').length || 0) && <div className="mb-4 rounded-2xl border border-[#0E4C92]/30 bg-[#0E4C92]/10 p-4"><p className="font-semibold text-[#0E4C92]">{completedCycles - (activity.data?.redemptions.filter((item: any) => item.status === 'applied').length || 0)} completed cycle reward{completedCycles - (activity.data?.redemptions.filter((item: any) => item.status === 'applied').length || 0) === 1 ? '' : 's'} not recorded</p><p className="mt-1 text-sm leading-6 text-[#0E4C92]">This customer has completed {completedCycles} loyalty cycle{completedCycles === 1 ? '' : 's'}, but no matching loyalty redemption record exists for the missing cycle{completedCycles - (activity.data?.redemptions.filter((item: any) => item.status === 'applied').length || 0) === 1 ? '' : 's'}. Loyalty rewards are sale-linked discounts, not birthday coupon rows. Use the counter billing flow for the next eligible reward; birthday coupons appear below when generated.</p><a href={`/new-sale?customer=${customerId}`} className="mt-3 inline-flex items-center gap-2 text-sm font-semibold text-[#0E4C92] hover:underline">Open billing <ArrowRight size={15} /></a></div>}{activity.data?.coupons.length || activity.data?.redemptions.length ? <div className="space-y-4">{activity.data?.coupons.map((coupon: any) => { const redemption = activity.data?.redemptions.find((item: any) => item.sale_id === coupon.redeemed_sale_id); return <div key={coupon.id} className="rounded-2xl border border-line p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-semibold">{coupon.coupon_code}</p><p className="mt-1 text-xs text-graphite">{coupon.discount_pct}% birthday discount · valid {formatDate(coupon.valid_on)}</p></div><Badge tone={redemptionTone(coupon.status)}>{coupon.status}</Badge></div><div className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-xs text-graphite"><span>Issued {formatDate(coupon.issued_on)}</span>{coupon.redeemed_at && <span>Redeemed {formatDateTime(coupon.redeemed_at)}</span>}{coupon.redeemed_sale_id && <span>Sale {coupon.redeemed_sale_id.slice(0, 8)}</span>}</div>{redemption && <div className="mt-3 rounded-xl bg-sand/50 p-3 text-xs"><span className="font-semibold">Loyalty redemption:</span> {redemption.method} · {redemption.discount_pct}% · <Badge tone={redemptionTone(redemption.status)}>{redemption.status}</Badge></div>}</div>})}{activity.data?.redemptions.filter((item: any) => !activity.data?.coupons.some((coupon: any) => coupon.redeemed_sale_id === item.sale_id)).map((redemption: any) => <div key={redemption.id} className="rounded-2xl border border-line p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-semibold">Loyalty {redemption.method} reward</p><p className="mt-1 text-xs text-graphite">{redemption.discount_pct}% discount · {formatDateTime(redemption.created_at)}</p></div><Badge tone={redemptionTone(redemption.status)}>{redemption.status}</Badge></div></div>)}</div> : <EmptyState icon={Ticket} title="No coupons or redemptions yet" description="Birthday coupons and loyalty reward redemptions will appear here with their current status." />}</Panel> : <Panel title="Messages">{activity.data?.messages.length ? <div className="space-y-3">{activity.data.messages.map((message: any) => <div key={message.id} className="rounded-2xl border border-line p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-[.12em] text-graphite">{message.channel}</p><p className="mt-2 text-sm leading-6">{message.body}</p></div><Badge tone={redemptionTone(message.status)}>{message.status}</Badge></div><p className="mt-3 text-xs text-graphite">{formatDateTime(message.created_at)}</p></div>)}</div> : <EmptyState icon={MessageCircle} title="No messages yet" description="Birthday and customer-care messages will appear here." />}</Panel>}</div>
}
function AdjustPairsDialog({ customer, onClose, onSaved, onToast }: { customer: CustomerOverview; onClose: () => void; onSaved: () => Promise<unknown>; onToast: (state: ToastState) => void }) {
  const [delta, setDelta] = useState('1')
  const [note, setNote] = useState('Manual loyalty adjustment')
  const [saving, setSaving] = useState(false)
  const submit = async () => {
    const pairsDelta = Number(delta)
    if (!Number.isInteger(pairsDelta) || pairsDelta === 0) { onToast({ message: 'Enter a non-zero whole number of pairs.', tone: 'error' }); return }
    if (note.trim().length < 3) { onToast({ message: 'Add a short reason for this adjustment.', tone: 'error' }); return }
    try {
      if (!supabase) throw new Error('Connect your Supabase database first.')
      setSaving(true)
      const { data: auth } = await supabase.auth.getUser()
      const { error } = await supabase.from('loyalty_ledger').insert({ customer_id: customer.id, pairs_delta: pairsDelta, reason: 'manual_adjustment', note: note.trim(), created_by: auth.user?.id || null })
      if (error) throw error
      await onSaved()
      onToast({ message: `${pairsDelta > 0 ? 'Added' : 'Removed'} ${Math.abs(pairsDelta)} pair${Math.abs(pairsDelta) === 1 ? '' : 's'} for ${customer.full_name}.`, tone: 'success' })
      onClose()
    } catch (error) { onToast({ message: safeError(error), tone: 'error' }) } finally { setSaving(false) }
  }
  return <Dialog title={`Adjust loyalty pairs · ${customer.full_name}`} onClose={onClose}><div className="space-y-5"><div className="rounded-xl border border-line bg-sand/50 p-4 text-sm"><p className="font-semibold">Current progress</p><p className="mt-1 text-graphite">{customer.progress_in_cycle}/{customer.cycle_size} pairs in the current cycle · {customer.total_pairs} total pairs.</p></div><Field label="Pair adjustment" hint="Use a positive number to add pairs or a negative number to remove them."><input className={inputClass} type="number" step="1" value={delta} onChange={event => setDelta(event.target.value)} autoFocus /></Field><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => setDelta(String(Number(delta || 0) + 1))}>+1 pair</Button><Button size="sm" variant="outline" onClick={() => setDelta(String(Number(delta || 0) + 5))}>+5 pairs</Button><Button size="sm" variant="outline" onClick={() => setDelta(String(Number(delta || 0) - 1))}>−1 pair</Button></div><Field label="Reason"><textarea className={textareaClass} rows={3} value={note} onChange={event => setNote(event.target.value)} placeholder="Why is this adjustment being made?" /></Field><div className="flex justify-end gap-2"><Button variant="ghost" onClick={onClose}>Cancel</Button><Button variant="secondary" loading={saving} onClick={submit}><Check size={16} /> Save adjustment</Button></div></div></Dialog>
}
function useParamsSafe() { const location = useLocation(); return { id: location.pathname.split('/')[2] || '' } }
function MetricCard({ label, value, helper, icon: Icon }: { label: string; value: string; helper?: string; icon: LucideIcon }) { return <div className="surface rounded-2xl border border-line bg-white/80 p-5 shadow-soft dark:bg-[#000000]"><div className="flex items-center gap-3"><div className="grid h-10 w-10 place-items-center rounded-xl bg-gold/15 text-gold"><Icon size={18} /></div><div><p className="text-xs uppercase tracking-[.1em] text-graphite">{label}</p><p className="mt-1 font-display text-2xl">{value}</p></div></div>{helper && <p className="mt-4 text-xs text-graphite">{helper}</p>}</div> }

function NewSalePage({ profile, onToast }: { profile: StaffProfile; onToast: (state: ToastState) => void }) { const [step, setStep] = useState(1); const [customer, setCustomer] = useState<CustomerOverview | null>(null); const [search, setSearch] = useState(''); const [items, setItems] = useState([{ product_name: '', sku: '', brand: '', size: '', quantity: 1, unit_price: 0, counts_for_loyalty: true, discount_eligible: true }]); const [discount, setDiscount] = useState<'none'|'birthday'|'loyalty_flat'|'loyalty_spin'>('none'); const [payment, setPayment] = useState('cash'); const [saving, setSaving] = useState(false); const [wheel, setWheel] = useState(false); const [rewardChoiceOpen, setRewardChoiceOpen] = useState(false); const [rewardEligible, setRewardEligible] = useState(false); const [pendingRewardCount, setPendingRewardCount] = useState(0); const [rewardSaleId, setRewardSaleId] = useState<string | null>(null); const [couponScannerOpen, setCouponScannerOpen] = useState(false); const [scannedCoupon, setScannedCoupon] = useState<any>(null); const [completedSale, setCompletedSale] = useState<any>(null); const quick = useQuery({ queryKey: ['sale-search', search], queryFn: async () => { if (!supabase || !search.trim()) return [] as CustomerOverview[]; const { data, error } = await supabase.rpc('search_customers', { p_query: search.trim(), p_limit: 5 }); if (error) throw error; return data as CustomerOverview[] }, enabled: Boolean(supabase && search.trim().length > 1) }); const settings = useQuery({ queryKey: ['loyalty-settings-sale'], queryFn: async () => { if (!supabase) return null; const { data, error } = await supabase.from('loyalty_settings').select('reward_mode,reward_flat_discount_pct').eq('id', 1).maybeSingle(); if (error) throw error; return data as { reward_mode: string; reward_flat_discount_pct: number } | null }, enabled: Boolean(supabase) }); const previewSubtotal = items.reduce((sum, item) => sum + Number(item.unit_price || 0) * Number(item.quantity || 0), 0); const selectCustomer = async (result: CustomerOverview) => { setCustomer(result); setScannedCoupon(null); setDiscount('none'); setRewardSaleId(null); setRewardEligible(Boolean(result.reward_ready)); setPendingRewardCount(0); setStep(2); try { if (!supabase) return; const { data: redemptions, error } = await supabase.from('loyalty_redemptions').select('id,status').eq('customer_id', result.id).eq('status', 'applied'); if (error) throw error; const pending = Math.max(0, Number(result.completed_cycles || 0) - (redemptions?.length || 0)); setPendingRewardCount(pending); setRewardEligible(Boolean(result.reward_ready) || pending > 0); if (result.reward_ready || pending > 0) { setRewardChoiceOpen(true); onToast({ message: `${result.full_name} has ${pending || 1} loyalty reward${(pending || 1) === 1 ? '' : 's'} available.`, tone: 'success' }) } } catch (error) { onToast({ message: safeError(error), tone: 'error' }) } }; const chooseReward = async (method: 'flat' | 'spin') => { if (!rewardSaleId) { setDiscount(method === 'spin' ? 'loyalty_spin' : 'loyalty_flat'); setRewardChoiceOpen(false); setStep(current => current === 3 ? 4 : 2); return } try { if (!supabase) throw new Error('Connect your Supabase database first.'); const { data, error } = await supabase.rpc('claim_loyalty_reward', { p_sale_id: rewardSaleId, p_method: method }); if (error) throw error; const { data: refreshedSale, error: saleError } = await supabase.from('sales').select('*').eq('id', rewardSaleId).single(); if (saleError) throw saleError; setCompletedSale(refreshedSale); setRewardSaleId(null); setRewardChoiceOpen(false); if (method === 'spin') { setWheel(true); setTimeout(() => { confetti({ particleCount: 130, spread: 75, origin: { y: .65 }, colors: ['#0E4C92','#000000','#FFFFFF'] }); setWheel(false); onToast({ message: `${customer?.full_name || 'Customer'} received ${data?.[0]?.out_discount_pct || ''}% from the wheel.`, tone: 'success' }) }, 1300) } else { onToast({ message: `${customer?.full_name || 'Customer'} received the 20% off-one-pair reward.`, tone: 'success' }) } } catch (error) { onToast({ message: safeError(error), tone: 'error' }) } }; const inspectCoupon = async (raw: string) => { try { if (!supabase) throw new Error('Connect your Supabase database first.'); const payload = parseCouponPayload(raw); if (!payload?.code) throw new Error('That QR does not contain a Goldstar coupon code.'); const { data: coupon, error } = await supabase.from('birthday_coupons').select('*, customers(id,full_name,phone)').eq('coupon_code', payload.code).maybeSingle(); if (error) throw error; if (!coupon) throw new Error(`Coupon ${payload.code} was not found.`); if (coupon.status !== 'issued') throw new Error(`Coupon ${coupon.coupon_code} is already ${coupon.status}.`); if (coupon.valid_on !== todayKathmandu()) throw new Error(`Coupon is valid only on ${coupon.valid_on}.`); const { data: overview, error: overviewError } = await supabase.from('customer_overview').select('*').eq('id', coupon.customer_id).maybeSingle(); if (overviewError) throw overviewError; if (!overview) throw new Error('The coupon customer is not available in customer_overview.'); setCustomer(overview as CustomerOverview); setScannedCoupon(coupon); setDiscount('birthday'); setCouponScannerOpen(false); setStep(4); onToast({ message: `Coupon verified for ${coupon.customers?.full_name || 'customer'} · ${coupon.discount_pct}% off.`, tone: 'success' }) } catch (error) { onToast({ message: safeError(error), tone: 'error' }) } }; const complete = async () => { try { if (!supabase) throw new Error('Connect your Supabase database to complete a sale.'); if (!items.some(item => item.product_name.trim())) throw new Error('Add at least one product before completing the sale.'); setSaving(true); const showroom = profile.showroom_id || (await supabase.from('showrooms').select('id').eq('is_active', true).limit(1).maybeSingle()).data?.id; if (!showroom) throw new Error('No active showroom is configured.'); const { data: sale, error } = await supabase.from('sales').insert({ showroom_id: showroom, customer_id: customer?.id || null, payment_method: payment, notes: null }).select('id').single(); if (error) throw error; const { error: itemError } = await supabase.from('sale_items').insert(items.filter(i => i.product_name.trim()).map(item => ({ sale_id: sale.id, sku: item.sku || null, product_name: item.product_name.trim(), brand: item.brand || null, size: item.size || null, quantity: item.quantity, unit_price: item.unit_price, counts_for_loyalty: item.counts_for_loyalty, discount_eligible: item.discount_eligible }))); if (itemError) throw itemError; if (discount === 'birthday') { const couponCode = scannedCoupon?.coupon_code || customer?.active_coupon_code; if (!couponCode) throw new Error('No valid birthday coupon is attached to this customer.'); const { error: discountError } = await supabase.rpc('apply_birthday_coupon', { p_code: couponCode, p_sale_id: sale.id }); if (discountError) throw discountError } else if (discount === 'loyalty_flat' || discount === 'loyalty_spin') { const { data, error: rewardError } = await supabase.rpc('claim_loyalty_reward', { p_sale_id: sale.id, p_method: discount === 'loyalty_spin' ? 'spin' : 'flat' }); if (rewardError) throw rewardError; if (discount === 'loyalty_spin') { setWheel(true); setTimeout(() => { confetti({ particleCount: 130, spread: 75, origin: { y: .65 }, colors: ['#0E4C92','#000000','#FFFFFF'] }); setWheel(false); onToast({ message: `Spin complete: ${data?.[0]?.out_segment_label || 'reward'} · ${data?.[0]?.out_discount_pct || ''}%`, tone: 'success' }) }, 1300) } } const { data: authoritativeSale, error: readBackError } = await supabase.from('sales').select('*').eq('id', sale.id).single(); if (readBackError) throw readBackError; const latestCustomer = customer ? (await supabase.from('customer_overview').select('*').eq('id', customer.id).maybeSingle()).data as CustomerOverview | null : null; setCompletedSale(authoritativeSale); if (latestCustomer) setCustomer(latestCustomer); onToast({ message: 'Sale completed. Final totals were read back from the database.', tone: 'success' }); setStep(5); if (latestCustomer && customer && latestCustomer.completed_cycles > customer.completed_cycles && discount === 'none') { setRewardSaleId(sale.id); setRewardChoiceOpen(true); onToast({ message: `${latestCustomer.full_name} completed cycle ${latestCustomer.completed_cycles}. Choose 20% off one pair or spin the 10/15/20/25% wheel.`, tone: 'success' }) } } catch (e) { onToast({ message: safeError(e), tone: 'error' }) } finally { setSaving(false) } }; return <PageFrame><SectionHeading eyebrow="Counter screen" title={pageInfo['/new-sale'][0]} description={pageInfo['/new-sale'][1]} action={<div className="flex items-center gap-2 text-xs text-graphite"><span className="grid h-7 w-7 place-items-center rounded-full bg-ink text-paper">{step}</span> of 4</div>} /><div className="mb-6 flex gap-2 overflow-x-auto">{['Customer','Items','Discount','Payment'].map((label, index) => <div key={label} className={cls('flex items-center gap-2 whitespace-nowrap rounded-xl px-3 py-2 text-xs font-semibold', step > index + 1 ? 'bg-gold/15 text-[#0E4C92]' : step === index + 1 ? 'bg-ink text-paper' : 'bg-sand text-graphite')}><span>{index + 1}</span>{label}</div>)}</div>{customer && <div className="mb-5 flex flex-wrap items-center gap-3 rounded-2xl border border-gold/30 bg-gold/10 p-4"><div className="grid h-9 w-9 place-items-center rounded-full bg-gold text-ink font-bold">{customer.full_name.slice(0,1)}</div><div className="flex-1"><p className="font-semibold">{customer.full_name}</p><p className="text-xs text-graphite">{customer.phone} · {customer.progress_in_cycle}/{customer.cycle_size} pairs</p></div>{customer.active_coupon_code && customer.active_coupon_valid_on === todayKathmandu() && <Badge tone="green">Birthday {customer.active_coupon_pct}% · {customer.active_coupon_code}</Badge>}{rewardEligible && <Badge tone="gold">{pendingRewardCount > 1 ? `${pendingRewardCount} loyalty rewards ready` : 'Loyalty reward ready'}</Badge>}</div>}<Panel>{step === 1 && <div><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-2xl">Who is this for?</h2><p className="mt-1 text-sm text-graphite">Attach a customer for rewards, coupons and a complete story.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => { setCustomer(null); setScannedCoupon(null); setStep(2) }}>Walk-in (no loyalty)</Button><Button variant="outline" onClick={() => setCouponScannerOpen(true)}><ScanLine size={16} /> Scan coupon</Button></div></div><div className="flex items-center gap-2 rounded-xl border border-line bg-paper/70 px-3"><Search size={17} className="text-graphite" /><input autoFocus value={search} onChange={e => setSearch(e.target.value)} placeholder="Search phone or name…" className="h-12 flex-1 bg-transparent outline-none" /></div><div className="mt-4 space-y-2">{quick.isLoading ? <SkeletonRows count={3} /> : quick.data?.length ? quick.data.map((result: CustomerOverview) => <button key={result.id} onClick={() => selectCustomer(result)} className="flex w-full items-center gap-3 rounded-xl border border-line p-3 text-left hover:border-gold"><div className="grid h-9 w-9 place-items-center rounded-full bg-sand font-display">{result.full_name.slice(0,1)}</div><span className="flex-1"><span className="block font-semibold">{result.full_name}</span><span className="block text-xs text-graphite">{result.phone} · {result.progress_in_cycle}/{result.cycle_size} pairs</span></span><ChevronRight size={16} className="text-graphite" /></button>) : <EmptyState icon={Search} title="Search a familiar name" description="Results are powered by the search_customers RPC. Misspellings are okay." />}</div></div>}{step === 2 && <div><div className="mb-5 flex items-center justify-between"><div><h2 className="font-display text-2xl">Add the pairs</h2><p className="mt-1 text-sm text-graphite">The preview is for speed. Final totals come from Supabase.</p></div><Badge tone="neutral">Preview {formatCurrency(previewSubtotal)}</Badge></div><div className="space-y-3">{items.map((item, index) => <div key={index} className="rounded-2xl border border-line p-4"><div className="grid gap-3 md:grid-cols-[1.6fr_1fr_1fr_1fr_auto]"><input className={inputClass} placeholder="Product name *" value={item.product_name} onChange={e => setItems(prev => prev.map((x,i) => i===index ? {...x,product_name:e.target.value} : x))} /><input className={inputClass} placeholder="SKU" value={item.sku} onChange={e => setItems(prev => prev.map((x,i) => i===index ? {...x,sku:e.target.value} : x))} /><input className={inputClass} placeholder="Brand" value={item.brand} onChange={e => setItems(prev => prev.map((x,i) => i===index ? {...x,brand:e.target.value} : x))} /><input className={inputClass} placeholder="Size" value={item.size} onChange={e => setItems(prev => prev.map((x,i) => i===index ? {...x,size:e.target.value} : x))} /><button disabled={items.length===1} onClick={() => setItems(prev => prev.filter((_,i)=>i!==index))} className="grid h-11 w-11 place-items-center rounded-xl text-graphite hover:bg-white hover:text-black"><X size={16} /></button></div><div className="mt-3 grid gap-3 sm:grid-cols-3"><label className="flex items-center gap-2 text-xs text-graphite"><input type="checkbox" className="accent-[#0E4C92]" checked={item.counts_for_loyalty} onChange={e=>setItems(prev=>prev.map((x,i)=>i===index?{...x,counts_for_loyalty:e.target.checked}:x))} /> Counts for loyalty</label><label className="flex items-center gap-2 text-xs text-graphite"><input type="checkbox" className="accent-[#0E4C92]" checked={item.discount_eligible} onChange={e=>setItems(prev=>prev.map((x,i)=>i===index?{...x,discount_eligible:e.target.checked}:x))} /> Discount eligible</label><div className="flex gap-2"><input type="number" min="1" className={cls(inputClass,'w-20')} value={item.quantity} onChange={e=>setItems(prev=>prev.map((x,i)=>i===index?{...x,quantity:Number(e.target.value)}:x))} /><input type="number" min="0" className={inputClass} placeholder="Unit price" value={item.unit_price || ''} onChange={e=>setItems(prev=>prev.map((x,i)=>i===index?{...x,unit_price:Number(e.target.value)}:x))} /></div></div></div>)}<Button variant="outline" onClick={() => setItems(prev => [...prev, { product_name:'', sku:'', brand:'', size:'', quantity:1, unit_price:0, counts_for_loyalty:true, discount_eligible:true }])}><Plus size={16} /> Add another item</Button></div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setStep(1)}>Back</Button><Button variant="secondary" onClick={() => setStep(customer ? 3 : 4)}>Continue <ArrowRight size={16} /></Button></div></div>}{step === 3 && <div><h2 className="font-display text-2xl">Choose one discount</h2><p className="mt-1 text-sm text-graphite">One bill, one gesture. Available actions are governed by the database.</p><div className="mt-6 grid gap-4 md:grid-cols-3">{(scannedCoupon || (customer?.active_coupon_code && customer.active_coupon_valid_on === todayKathmandu())) && <DiscountOption icon={Cake} title={`Birthday · ${scannedCoupon?.discount_pct ?? customer?.active_coupon_pct}%`} detail={`Apply ${scannedCoupon?.coupon_code || customer?.active_coupon_code}`} onClick={() => { setDiscount('birthday'); setStep(4) }} />}{rewardEligible && <DiscountOption icon={Gift} title="Loyalty reward" detail="Choose flat or spin" onClick={() => setRewardChoiceOpen(true)} />}{!customer?.active_coupon_code && !rewardEligible && <EmptyState icon={Tag} title="No discount available" description="Complete the sale without a discount. You can still grow the loyalty card." />}</div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setStep(2)}>Back</Button><Button variant="outline" onClick={() => { setDiscount('none'); setStep(4) }}>Continue without discount</Button></div></div>}{step === 4 && <div><h2 className="font-display text-2xl">Take payment</h2><p className="mt-1 text-sm text-graphite">Confirm the method, then let the database settle the bill.</p><div className="mt-6 grid gap-3 sm:grid-cols-2">{['cash','card','esewa','khalti','fonepay','bank_transfer','other'].map(method => <button key={method} onClick={() => setPayment(method)} className={cls('rounded-xl border p-4 text-left text-sm font-semibold capitalize', payment===method ? 'border-gold bg-gold/10' : 'border-line')}>{method.replace('_',' ')}</button>)}</div><textarea className={cls(textareaClass,'mt-5')} rows={3} placeholder="Notes for the bill (optional)" /><div className="mt-6 rounded-2xl bg-ink p-5 text-paper"><div className="flex items-center justify-between"><span className="text-sm text-white/60">Preview total</span><span className="font-display text-2xl">{formatCurrency(previewSubtotal)}</span></div><p className="mt-2 text-xs text-white/45">The final subtotal, discount and total are read from the database after completion.</p></div><div className="mt-6 flex justify-end gap-2"><Button variant="ghost" onClick={() => setStep(customer ? 3 : 2)}>Back</Button><Button variant="secondary" loading={saving} onClick={complete}>Complete sale <Check size={16} /></Button></div></div>}{step === 5 && <SuccessSale customer={customer} sale={completedSale} />}</Panel>{couponScannerOpen && <Dialog title="Scan birthday coupon" onClose={() => setCouponScannerOpen(false)}><CouponScanner onDecoded={inspectCoupon} onClose={() => setCouponScannerOpen(false)} /></Dialog>}{rewardChoiceOpen && <Dialog title={rewardSaleId ? 'Cycle complete — choose the reward' : 'Choose the loyalty reward'} onClose={() => setRewardChoiceOpen(false)}><p className="mb-5 text-sm leading-6 text-graphite">{rewardSaleId ? 'The 10th pair has been recorded. Apply the reward to this completed bill now.' : 'This customer has an unclaimed loyalty reward. Choose the configured reward before continuing billing; it will be claimed only after the sale is completed.'}</p><div className="grid gap-3 sm:grid-cols-2">{(!settings.data?.reward_mode || settings.data.reward_mode === 'flat' || settings.data.reward_mode === 'customer_choice') && <button onClick={() => { chooseReward('flat') }} className="rounded-2xl border border-line p-4 text-left hover:border-gold"><p className="font-display text-xl">Flat {settings.data?.reward_flat_discount_pct ?? 20}% off one pair</p><p className="mt-1 text-xs text-graphite">Use the live flat discount setting.</p></button>}{(!settings.data?.reward_mode || settings.data.reward_mode === 'spin' || settings.data.reward_mode === 'customer_choice') && <button onClick={() => { chooseReward('spin') }} className="rounded-2xl border border-line p-4 text-left hover:border-gold"><p className="font-display text-xl">Spin the wheel</p><p className="mt-1 text-xs text-graphite">The server decides between the configured 10%, 15%, 20% and 25% segments.</p></button>}</div></Dialog>}{wheel && <div className="fixed inset-0 z-50 grid place-items-center bg-ink/80 p-4"><div className="text-center text-paper"><div className="mx-auto grid h-56 w-56 animate-[spin_1.3s_cubic-bezier(.2,.8,.2,1)] place-items-center rounded-full border-[12px] border-gold bg-[conic-gradient(#0E4C92_0_20%,#000000_20%_40%,#FFFFFF_40%_60%,#0E4C92_60%_80%,#000000_80%)] shadow-gold"><span className="grid h-20 w-20 place-items-center rounded-full bg-ink font-display text-3xl text-gold">★</span></div><p className="mt-8 font-display text-3xl">Finding your reward…</p><p className="mt-2 text-sm text-white/55">The result is already locked by Supabase.</p></div></div>}</PageFrame> }
function DiscountOption({ icon: Icon, title, detail, onClick }: { icon: LucideIcon; title: string; detail: string; onClick: () => void }) { return <button onClick={onClick} className="group rounded-2xl border border-line p-5 text-left transition hover:-translate-y-0.5 hover:border-gold hover:shadow-gold"><div className="mb-5 grid h-11 w-11 place-items-center rounded-2xl bg-gold/15 text-gold"><Icon size={20} /></div><p className="font-display text-xl">{title}</p><p className="mt-1 text-sm text-graphite">{detail}</p><ArrowRight size={17} className="mt-5 text-graphite transition group-hover:translate-x-1" /></button> }
function SuccessSale({ customer, sale }: { customer: CustomerOverview | null; sale: any }) { return <div className="mx-auto max-w-lg text-center"><div className="mx-auto mb-6 grid h-16 w-16 place-items-center rounded-full bg-white text-[#0E4C92]"><Check size={30} /></div><p className="mb-2 text-[11px] font-bold uppercase tracking-[.18em] text-gold">Sale complete</p><h2 className="font-display text-4xl">That one’s in the books.</h2><p className="mt-3 text-sm text-graphite">Final totals are from the database. The customer’s progress will be ready for the next conversation.</p><div className="mx-auto mt-7 max-w-xs border-y border-dashed border-line py-5 text-left"><div className="flex justify-between text-sm"><span className="text-graphite">Final total</span><strong>{formatCurrency(sale?.total_amount)}</strong></div>{customer && <div className="mt-3 flex justify-between text-sm"><span className="text-graphite">Loyalty progress</span><strong>{customer.progress_in_cycle}/{customer.cycle_size} pairs</strong></div>}</div><div className="mt-7 flex justify-center gap-2"><Button variant="outline" onClick={() => window.print()}><ReceiptText size={16} /> Print receipt</Button><Button variant="secondary" onClick={() => window.location.reload()}>New sale <ArrowRight size={16} /></Button></div></div> }

function SalesPage({ role, onToast }: { role: Role; onToast: (state: ToastState) => void }) { const [status, setStatus] = useState('completed'); const sales = useQuery({ queryKey: ['sales', status], queryFn: async () => { if (!supabase) return []; const { data, error } = await supabase.from('sales').select('*, customers(full_name,phone)').eq('status', status).order('sale_date', { ascending: false }).range(0,24); if (error) throw error; return data || [] }, enabled: Boolean(supabase) }); const rows = sales.data || []; return <PageFrame><SectionHeading eyebrow="Transactions" title={pageInfo['/sales'][0]} description={pageInfo['/sales'][1]} action={<Button variant="secondary" onClick={() => window.location.href='/new-sale'}><Plus size={17} /> New sale</Button>} /><div className="mb-5 flex flex-wrap gap-2">{['completed','voided'].map(item => <button key={item} onClick={() => setStatus(item)} className={cls('rounded-xl px-3 py-2 text-xs font-semibold capitalize', status===item?'bg-ink text-paper':'border border-line text-graphite')}>{item}</button>)}<button className="rounded-xl border border-line px-3 py-2 text-xs font-semibold text-graphite">Date range</button><button className="rounded-xl border border-line px-3 py-2 text-xs font-semibold text-graphite">Payment method</button></div><Panel title="Sales ledger" action={<span className="text-xs text-graphite">Server-paginated · latest 25</span>}>{sales.isLoading ? <SkeletonRows count={6} /> : sales.error ? <InlineError message={safeError(sales.error)} /> : rows.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.12em] text-graphite"><th className="pb-3">Invoice</th><th className="pb-3">Customer</th><th className="pb-3">Date</th><th className="pb-3">Total</th><th className="pb-3">Discount</th><th className="pb-3">Status</th><th /></tr></thead><tbody className="divide-y divide-line">{rows.map((sale: any) => <tr key={sale.id}><td className="py-4 font-mono text-sm">{sale.invoice_no}</td><td className="py-4"><span className="block text-sm font-semibold">{sale.customers?.full_name || 'Walk-in'}</span><span className="text-xs text-graphite">{sale.customers?.phone || 'No loyalty'}</span></td><td className="py-4 text-sm text-graphite">{formatDateTime(sale.sale_date)}</td><td className="py-4 font-semibold">{formatCurrency(sale.total_amount)}</td><td className="py-4"><span className="text-sm">{sale.discount_pct ? `${sale.discount_pct}%` : '—'}</span><span className="block text-[10px] uppercase tracking-[.1em] text-graphite">{sale.discount_type}</span></td><td className="py-4"><Badge tone={sale.status==='completed'?'green':'red'}>{sale.status}</Badge></td><td className="py-4 text-right"><a href={`/sales/${sale.id}`} className="text-graphite hover:text-ink"><ChevronRight size={17} /></a></td></tr>)}</tbody></table></div> : <EmptyState icon={ReceiptText} title="No sales in this view" description="Completed and voided bills will appear here as the counter gets moving." action={<Button variant="outline" onClick={() => window.location.href='/new-sale'}><Plus size={16} /> Start the first sale</Button>} />}</Panel></PageFrame> }
function SaleDetailPage({ role, onToast }: { role: Role; onToast: (state: ToastState) => void }) { const { id } = useParamsSafe(); const sale = useQuery({ queryKey: ['sale', id], queryFn: async () => { if (!supabase) return null; const { data, error } = await supabase.from('sales').select('*, customers(full_name,phone), sale_items(*)').eq('id', id).maybeSingle(); if (error) throw error; return data }, enabled: Boolean(supabase && id) }); if (sale.isLoading) return <SkeletonRows count={5} />; if (sale.error) return <InlineError message={safeError(sale.error)} />; if (!sale.data) return <EmptyState icon={ReceiptText} title="Sale not found" description="This bill is not available in the connected database." />; const data: any = sale.data; return <PageFrame><a href="/sales" className="mb-5 inline-flex items-center gap-2 text-sm text-graphite">← Back to sales</a><SectionHeading eyebrow="Sale detail" title={data.invoice_no} description={`${data.customers?.full_name || 'Walk-in'} · ${formatDateTime(data.sale_date)}`} action={isManager(role) && data.status==='completed' ? <Button variant="danger" onClick={() => onToast({ message: 'Void flow requires a reason and will reverse loyalty pairs.', tone: 'error' })}>Void sale</Button> : <Badge tone={data.status==='completed'?'green':'red'}>{data.status}</Badge>} /><div className="grid gap-6 lg:grid-cols-[1fr_.7fr]"><Panel title="Items"><div className="divide-y divide-line">{(data.sale_items || []).map((item: any) => <div key={item.id} className="flex items-center justify-between py-4"><div><p className="font-semibold">{item.product_name}</p><p className="text-xs text-graphite">{item.sku || 'No SKU'} · Qty {item.quantity}</p></div><p className="font-semibold">{formatCurrency(item.line_total)}</p></div>)}</div></Panel><Panel title="Totals"><div className="space-y-4 text-sm"><div className="flex justify-between"><span className="text-graphite">Subtotal</span><strong>{formatCurrency(data.subtotal)}</strong></div><div className="flex justify-between"><span className="text-graphite">Discount · {data.discount_type}</span><strong>{data.discount_pct ? `${data.discount_pct}%` : '—'}</strong></div><div className="flex justify-between border-t border-dashed border-line pt-4 text-lg"><span>Total</span><strong className="font-display">{formatCurrency(data.total_amount)}</strong></div><div className="rounded-xl bg-sand/60 p-3 text-xs text-graphite">Voiding a sale automatically reverses loyalty pairs and releases coupons through the database.</div></div></Panel></div></PageFrame> }

function BirthdaysPage({ onToast }: { onToast: (state: ToastState) => void }) {
  const [range, setRange] = useState(7)
  const [couponStatus, setCouponStatus] = useState('issued')
  const [generating, setGenerating] = useState(false)
  const [selectedBirthday, setSelectedBirthday] = useState<CustomerOverview | null>(null)
  const [messageText, setMessageText] = useState('')
  const birthdays = useQuery({ queryKey: ['birthday-customers', range], queryFn: async () => {
    if (!supabase) return [] as CustomerOverview[]
    const { data, error } = await supabase.from('customer_overview').select('*').not('date_of_birth', 'is', null).eq('is_active', true)
    if (error) throw error
    const today = new Date()
    const start = new Date(today.getFullYear(), today.getMonth(), today.getDate())
    const occurrenceFor = (raw: string) => {
      const dob = new Date(`${raw}T00:00:00`)
      const leap = (year: number) => year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0)
      const day = dob.getMonth() === 1 && dob.getDate() === 29 && !leap(start.getFullYear()) ? 28 : dob.getDate()
      let occurrence = new Date(start.getFullYear(), dob.getMonth(), day)
      if (occurrence < start) { const nextYear = start.getFullYear() + 1; const nextDay = dob.getMonth() === 1 && dob.getDate() === 29 && !leap(nextYear) ? 28 : dob.getDate(); occurrence = new Date(nextYear, dob.getMonth(), nextDay) }
      return occurrence
    }
    return (data || []).map(customer => ({ customer, occurrence: occurrenceFor(customer.date_of_birth as string) })).filter(item => { const end = new Date(start); end.setDate(end.getDate() + range); return item.occurrence >= start && item.occurrence <= end }).sort((a, b) => a.occurrence.getTime() - b.occurrence.getTime()).map(item => item.customer)
  }, enabled: Boolean(supabase) })
  const coupons = useQuery({ queryKey: ['birthday-coupons', couponStatus], queryFn: async () => { if (!supabase) return []; let query = supabase.from('birthday_coupons').select('*, customers(full_name,phone)').order('valid_on', { ascending: true }).limit(80); if (couponStatus !== 'all') query = query.eq('status', couponStatus); const { data, error } = await query; if (error) throw error; return data || [] }, enabled: Boolean(supabase) })
  const template = useQuery({ queryKey: ['birthday-template'], queryFn: async () => { if (!supabase) return null; const { data } = await supabase.from('message_templates').select('body').eq('kind', 'birthday_coupon').eq('channel', 'sms').eq('is_active', true).maybeSingle(); return data }, enabled: Boolean(supabase) })
  const settings = useQuery({ queryKey: ['loyalty-settings-message'], queryFn: async () => { if (!supabase) return null; const { data } = await supabase.from('loyalty_settings').select('shop_name').eq('id', 1).maybeSingle(); return data }, enabled: Boolean(supabase) })
  const selectedCoupon = selectedBirthday ? coupons.data?.find((coupon: any) => coupon.coupon_code === selectedBirthday.active_coupon_code) : null
  const shareCoupon = selectedBirthday && (selectedCoupon || (selectedBirthday.active_coupon_code ? { coupon_code: selectedBirthday.active_coupon_code, discount_pct: selectedBirthday.active_coupon_pct, valid_on: selectedBirthday.active_coupon_valid_on, customers: { full_name: selectedBirthday.full_name, phone: selectedBirthday.phone } } : null))
  useEffect(() => { if (!selectedBirthday) return; const fallback = 'Hi {{name}}, your {{discount}}% Goldstar birthday reward {{code}} is ready for {{date}}. — {{shop}}'; setMessageText(renderTemplate(template.data?.body || fallback, { name: selectedBirthday.full_name, discount: selectedBirthday.active_coupon_pct, code: selectedBirthday.active_coupon_code, date: selectedBirthday.active_coupon_valid_on, shop: settings.data?.shop_name || 'Goldstar Banepa' })) }, [selectedBirthday, template.data?.body, settings.data?.shop_name])
  const generate = async () => { try { if (!supabase) throw new Error('Connect your database first.'); setGenerating(true); const { data, error } = await supabase.rpc('generate_birthday_coupons', { p_days_ahead: range }); if (error) throw error; await Promise.all([birthdays.refetch(), coupons.refetch()]); onToast({ message: `${data || 0} birthday coupon(s) generated and refreshed.`, tone: 'success' }) } catch (error) { onToast({ message: safeError(error), tone: 'error' }) } finally { setGenerating(false) } }
  const queueMessage = async () => { try { if (!supabase || !selectedBirthday) throw new Error('Choose a birthday customer first.'); if (!selectedBirthday.sms_consent) throw new Error('This customer has not consented to SMS.'); if (!messageText.trim()) throw new Error('Write a message before queueing it.'); const { error } = await supabase.from('message_log').insert({ customer_id: selectedBirthday.id, kind: 'birthday_coupon', channel: 'sms', phone: selectedBirthday.phone, body: messageText.trim(), status: 'queued', related_coupon_id: selectedCoupon?.id || null }); if (error) throw error; onToast({ message: `Birthday message queued for ${selectedBirthday.full_name}.`, tone: 'success' }); setSelectedBirthday(null) } catch (error) { onToast({ message: safeError(error), tone: 'error' }) } }
  const copyCode = async (code: string) => { await navigator.clipboard?.writeText(code); onToast({ message: `Copied coupon ${code}.`, tone: 'success' }) }
  return <PageFrame><SectionHeading eyebrow="Loyalty care desk" title="Birthdays, messages and digital rewards." description="One place to generate a birthday coupon, make the message feel human, and hand the customer a QR that the counter can redeem." action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => window.location.href='/new-sale'}><ScanLine size={16} /> Redeem a QR</Button><Button variant="secondary" loading={generating} onClick={generate}><Ticket size={17} /> Generate coupons</Button></div>} /><div className="mb-5 flex flex-wrap gap-2">{[7, 30, 90].map(days => <button key={days} onClick={() => setRange(days)} className={cls('rounded-xl px-3 py-2 text-xs font-semibold', range === days ? 'bg-ink text-paper' : 'border border-line text-graphite')}>{days} days</button>)}</div><div className="grid gap-6 xl:grid-cols-[.9fr_1.1fr]"><Panel eyebrow="Click a customer to write" title={`Upcoming in ${range} days`} action={<Badge tone="gold">Editable birthday messages</Badge>}>{birthdays.isLoading ? <SkeletonRows count={5} /> : birthdays.error ? <InlineError message={safeError(birthdays.error)} /> : birthdays.data?.length ? <div className="divide-y divide-line">{birthdays.data.map(customer => <button key={customer.id} onClick={() => setSelectedBirthday(customer)} className="flex w-full items-center gap-3 py-4 text-left transition hover:bg-gold/5"><div className="grid h-10 w-10 place-items-center rounded-full bg-gold/15 text-gold"><Cake size={17} /></div><div className="min-w-0 flex-1"><p className="truncate font-semibold">{customer.full_name}</p><p className="text-xs text-graphite">{customer.phone} · {formatDate(customer.date_of_birth)}</p></div>{customer.active_coupon_code ? <Badge tone="green">{customer.active_coupon_pct}% coupon</Badge> : <Badge tone="neutral">Generate coupon</Badge>}<MessageCircle size={17} className="text-graphite" /></button>)}</div> : <EmptyState icon={Cake} title="No birthdays in this window" description="Upcoming customers will appear from the connected database. Try 30 or 90 days." />}</Panel><Panel eyebrow="Digital coupon shelf" title="Issued rewards with QR codes" action={<div className="flex gap-2">{['issued','redeemed','expired','all'].map(status => <button key={status} onClick={() => setCouponStatus(status)} className={cls('rounded-lg px-2.5 py-1.5 text-[11px] font-semibold capitalize', couponStatus === status ? 'bg-ink text-paper' : 'border border-line text-graphite')}>{status}</button>)}</div>}>{coupons.isLoading ? <SkeletonRows count={3} /> : coupons.error ? <InlineError message={safeError(coupons.error)} /> : coupons.data?.length ? <div className="space-y-4">{coupons.data.slice(0, 4).map((coupon: any) => <DigitalCouponCard key={coupon.id} coupon={coupon} onCopy={copyCode} onToast={onToast} onMessage={() => { const customer = birthdays.data?.find(item => item.id === coupon.customer_id); if (customer) setSelectedBirthday(customer) }} />)}</div> : <EmptyState icon={QrCode} title="No digital coupons yet" description="Generate the next birthday window and each database-issued coupon will appear here with a scannable QR." />}</Panel></div><div className="mt-6 rounded-2xl border border-gold/30 bg-gold/10 p-5"><div className="flex items-start gap-3"><Gift className="mt-0.5 text-[#0E4C92]" size={20} /><div><p className="font-semibold text-[#0E4C92]">How redemption works</p><p className="mt-1 text-sm leading-6 text-[#0E4C92]">The QR encodes only the coupon code. At the counter, scan or paste it in Redeem discount; Goldstar looks up the exact database coupon and applies the discount through `apply_birthday_coupon` after the sale is created. No discount amount is calculated in the browser.</p></div></div></div>{selectedBirthday && <Dialog title={`Write to ${selectedBirthday.full_name}`} onClose={() => setSelectedBirthday(null)}><div className="space-y-5"><div className="rounded-2xl bg-sand/60 p-4"><div className="flex items-center justify-between"><div><p className="font-semibold">Birthday reward context</p><p className="mt-1 text-xs text-graphite">{selectedBirthday.phone} · {selectedBirthday.active_coupon_code || 'No active coupon yet'}</p></div>{selectedBirthday.active_coupon_pct && <Badge tone="gold">{selectedBirthday.active_coupon_pct}% off</Badge>}</div></div>{!selectedBirthday.sms_consent && <div className="rounded-xl bg-white p-3 text-sm text-black"><AlertCircle size={16} className="mr-2 inline" />SMS consent is off. You can edit the draft, but queueing is disabled.</div>}<Field label="Editable SMS body" hint="Placeholders are rendered from the selected customer and coupon."><textarea className={cls(textareaClass, 'min-h-36')} value={messageText} onChange={event => setMessageText(event.target.value)} /></Field><div className="rounded-xl border border-line p-3 text-sm"><p className="mb-1 text-[10px] font-bold uppercase tracking-[.12em] text-gold">Preview</p>{messageText || 'Your editable birthday message preview will appear here.'}</div>{shareCoupon && <div className="flex flex-wrap justify-end gap-2"><ShareCouponCard coupon={shareCoupon} message={messageText} shopName={settings.data?.shop_name || 'Goldstar Banepa'} onToast={onToast} /><Button variant="ghost" onClick={() => setSelectedBirthday(null)}>Cancel</Button><Button variant="secondary" disabled={!selectedBirthday.sms_consent} onClick={queueMessage}><Send size={16} /> Queue message</Button></div>}</div></Dialog>}</PageFrame>
}

function MessagesPage({ onToast }: { onToast: (state: ToastState) => void }) { const [status, setStatus] = useState('queued'); const messages = useQuery({ queryKey: ['messages', status], queryFn: async () => { if (!supabase) return []; let query = supabase.from('message_log').select('*, customers(full_name)').order('created_at',{ascending:false}).limit(50); if (status !== 'all') query = query.eq('status', status); const { data, error } = await query; if (error) throw error; return data || [] }, enabled: Boolean(supabase) }); const run = async (mode: 'queued'|'failed') => { try { if (!supabase) throw new Error('Connect your Supabase database first.'); const { data, error } = await supabase.functions.invoke('send-sms', { body: { mode } }); if (error) throw error; onToast({ message: `${data?.sent || 0} message(s) sent.`, tone: 'success' }) } catch (e) { onToast({ message: safeError(e), tone: 'error' }) } }; return <PageFrame><SectionHeading eyebrow="Customer care" title={pageInfo['/messages'][0]} description={pageInfo['/messages'][1]} action={<div className="flex gap-2"><Button variant="outline" onClick={() => run('failed')}><RefreshCw size={15} /> Retry failed</Button><Button variant="secondary" onClick={() => run('queued')}><Mail size={15} /> Send queued</Button></div>} /><div className="mb-5 flex gap-2">{['queued','sent','failed','all'].map(item => <button key={item} onClick={() => setStatus(item)} className={cls('rounded-xl px-3 py-2 text-xs font-semibold capitalize', status===item?'bg-ink text-paper':'border border-line text-graphite')}>{item}</button>)}</div><Panel title="Message log">{messages.isLoading ? <SkeletonRows count={6} /> : messages.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.12em] text-graphite"><th className="pb-3">Customer</th><th className="pb-3">Message</th><th className="pb-3">Channel</th><th className="pb-3">Status</th><th className="pb-3">Created</th></tr></thead><tbody className="divide-y divide-line">{messages.data.map((m: any) => <tr key={m.id}><td className="py-4"><p className="font-semibold">{m.customers?.full_name || 'Customer'}</p><p className="text-xs text-graphite">{m.phone}</p></td><td className="max-w-sm py-4 text-sm text-graphite">{m.body}</td><td className="py-4 text-sm">{m.channel}</td><td className="py-4"><Badge tone={m.status==='sent'?'green':m.status==='failed'?'red':'gold'}>{m.status}</Badge>{m.error && <p className="mt-1 text-xs text-black">{m.error}</p>}</td><td className="py-4 text-sm text-graphite">{formatDateTime(m.created_at)}</td></tr>)}</tbody></table></div> : <EmptyState icon={Mail} title="No messages yet" description="Queued, sent and failed messages from the connected database will appear here." />}</Panel></PageFrame> }

function LegacyImportPage({ onToast }: { onToast: (state: ToastState) => void }) { const [file, setFile] = useState<File | null>(null); const [rows, setRows] = useState<Record<string,string>[]>([]); const [busy, setBusy] = useState(false); const parse = (selected: File) => { setFile(selected); Papa.parse<Record<string,string>>(selected, { header: true, skipEmptyLines: true, complete: results => setRows(results.data.slice(0, 20)) }) }; const process = async () => { try { if (!supabase) throw new Error('Connect your database first.'); if (!rows.length) throw new Error('Choose a CSV with at least one valid row.'); setBusy(true); onToast({ message: 'CSV preview is ready. Staging will run against your connected schema.', tone: 'success' }) } catch (e) { onToast({ message: safeError(e), tone: 'error' }) } finally { setBusy(false) } }; return <PageFrame><SectionHeading eyebrow="Data continuity" title={pageInfo['/legacy-import'][0]} description={pageInfo['/legacy-import'][1]} action={<Button variant="outline"><Download size={16} /> Download sample CSV</Button>} /><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><Panel title="1. Upload CSV"><div className="rounded-2xl border-2 border-dashed border-line p-8 text-center"><input id="legacy-file" className="hidden" type="file" accept=".csv,text/csv" onChange={e => e.target.files?.[0] && parse(e.target.files[0])} /><label htmlFor="legacy-file" className="cursor-pointer"><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-gold/15 text-gold"><Upload size={21} /></div><p className="font-semibold">{file ? file.name : 'Choose a CSV file'}</p><p className="mt-1 text-xs text-graphite">Auto-map phone, name, DOB, pairs, spend and last purchase.</p></label></div><div className="mt-5 rounded-xl bg-sand/60 p-4 text-xs leading-5 text-graphite"><strong className="text-ink">No records are written during preview.</strong> Existing phones are warned in chunks of 200. Valid rows are staged in chunks of 500, then processed by the database RPC.</div><Button className="mt-5 w-full" variant="secondary" loading={busy} onClick={process}>Validate and prepare import <ArrowRight size={16} /></Button></Panel><Panel title="2. Preview first 20 rows" action={rows.length ? <Badge tone="gold">{rows.length} shown</Badge> : undefined}>{rows.length ? <div className="overflow-auto"><table className="w-full min-w-[640px] text-left text-xs"><thead><tr className="border-b border-line uppercase tracking-[.1em] text-graphite"><th className="pb-3">Phone</th><th className="pb-3">Full name</th><th className="pb-3">DOB raw</th><th className="pb-3">Pairs</th><th className="pb-3">Spend</th></tr></thead><tbody className="divide-y divide-line">{rows.map((row,index) => <tr key={index}><td className="py-3">{row.phone || row.phone_raw || '—'}</td><td className="py-3 font-semibold">{row.full_name || '—'}</td><td className="py-3">{row.date_of_birth || '—'}</td><td className="py-3">{row.total_pairs || '—'}</td><td className="py-3">{row.total_spend || '—'}</td></tr>)}</tbody></table></div> : <EmptyState icon={Upload} title="Preview will appear here" description="Upload a CSV to map and validate legacy data before anything is staged." />}</Panel></div></PageFrame> }

function ReportsPage() { const [range, setRange] = useState('30'); const chartData = [{ name:'Mon', sales:0 },{ name:'Tue', sales:0 },{ name:'Wed', sales:0 },{ name:'Thu', sales:0 },{ name:'Fri', sales:0 },{ name:'Sat', sales:0 },{ name:'Sun', sales:0 }]; return <PageFrame><SectionHeading eyebrow="Business intelligence" title={pageInfo['/reports'][0]} description={pageInfo['/reports'][1]} action={<div className="flex gap-2"><select className={inputClass} value={range} onChange={e=>setRange(e.target.value)}><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option></select><Button variant="outline"><Download size={16} /> Export tables</Button></div>} /><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Bills" value="—" helper={`Last ${range} days · completed`} icon={ReceiptText} /><StatCard label="Gross sales" value="Rs. —" helper="Sum of completed totals" icon={CircleDollarSign} /><StatCard label="Discount given" value="Rs. —" helper="Database-owned discount amount" icon={Tag} /><StatCard label="Discounted share" value="—" helper="Bills with a discount" icon={TrendingUp} /></div><div className="grid gap-6 lg:grid-cols-[1.4fr_.6fr]"><Panel title="Sales by day" eyebrow="Completed bills"><div className="h-72"><ResponsiveContainer width="100%" height="100%"><LineChart data={chartData}><CartesianGrid strokeDasharray="3 3" stroke="#000000" /><XAxis dataKey="name" tickLine={false} axisLine={false} /><YAxis tickLine={false} axisLine={false} /><Tooltip /><Line type="monotone" dataKey="sales" stroke="#0E4C92" strokeWidth={3} dot={{ fill:'#000000', r:4 }} /></LineChart></ResponsiveContainer></div></Panel><Panel title="Redemptions" eyebrow="Applied methods"><div className="h-72"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{name:'Flat',value:1},{name:'Spin',value:1}]} dataKey="value" innerRadius={55} outerRadius={88} paddingAngle={5}><Cell fill="#0E4C92" /><Cell fill="#000000" /></Pie><Legend /></PieChart></ResponsiveContainer></div></Panel></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><Panel title="Discount amount by type"><EmptyState icon={BarChart3} title="Reports wake up with your first sale" description="Discount totals and redemption rates will be aggregated from the connected tables." /></Panel><Panel title="Top 10 customers by lifetime spend"><EmptyState icon={Users} title="No customer spend yet" description="Customer overview lifetime spend will appear here once data is connected." /></Panel></div></PageFrame> }

function SettingsPage({ onToast }: { onToast: (state: ToastState) => void }) { const [mode, setMode] = useState('customer_choice'); const [saved, setSaved] = useState(false); return <PageFrame><SectionHeading eyebrow="Admin controls" title={pageInfo['/settings'][0]} description={pageInfo['/settings'][1]} action={<Button variant="secondary" onClick={() => { setSaved(true); onToast({ message: 'Settings save is ready for your connected database.', tone: 'success' }) }}><Check size={16} /> Save settings</Button>} /><div className="grid gap-6 lg:grid-cols-2"><Panel title="Loyalty settings" eyebrow="Database row id = 1"><div className="space-y-5"><Field label="Shop name"><input className={inputClass} defaultValue="Goldstar Banepa" /></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Pairs for reward" hint="Minimum 2"><input className={inputClass} type="number" min="2" defaultValue="10" /></Field><Field label="Flat discount %"><input className={inputClass} type="number" min="0" max="100" defaultValue="25" /></Field></div><Field label="Reward mode"><select className={inputClass} value={mode} onChange={e=>setMode(e.target.value)}><option value="flat">Flat discount</option><option value="spin">Spin the wheel</option><option value="customer_choice">Customer choice</option></select></Field><div className="space-y-3 text-sm"><label className="flex items-center gap-2"><input type="checkbox" className="accent-[#0E4C92]" defaultChecked /> Birthday coupons enabled</label><label className="flex items-center gap-2"><input type="checkbox" className="accent-[#0E4C92]" defaultChecked /> Birthday applies to discounted items</label></div></div></Panel><Panel title="Birthday tiers" eyebrow="Unique minimum values"><div className="space-y-3"><TierRow label="Everyday thank-you" min="0" pct="10" /><TierRow label="Gold regular" min="25000" pct="15" /><TierRow label="Signature customer" min="75000" pct="25" /><Button variant="outline" size="sm"><Plus size={15} /> Add tier</Button></div></Panel><Panel title="Wheel segments" eyebrow="Live win probability"><div className="space-y-3"><WheelRow label="5% off" color="#0E4C92" weight="35" /><WheelRow label="10% off" color="#000000" weight="25" /><WheelRow label="15% off" color="#FFFFFF" weight="20" /><WheelRow label="25% off" color="#0E4C92" weight="20" /></div><div className="mt-5 flex items-center justify-center"><div className="grid h-36 w-36 place-items-center rounded-full border-8 border-paper bg-[conic-gradient(#0E4C92_0_35%,#000000_35%_60%,#FFFFFF_60%_80%,#0E4C92_80%)] shadow-gold"><span className="grid h-12 w-12 place-items-center rounded-full bg-ink text-gold">★</span></div></div></Panel><Panel title="Message templates" eyebrow="Placeholder-aware"><div className="space-y-4"><Field label="Birthday coupon · SMS"><textarea className={textareaClass} rows={4} defaultValue="Hi {{name}}, your {{discount}}% Goldstar birthday reward {{code}} is ready for {{date}}. — {{shop}}" /></Field><p className="text-xs text-graphite">Available placeholders: {'{{name}}'} {'{{discount}}'} {'{{code}}'} {'{{date}}'} {'{{shop}}'}</p><div className="rounded-xl bg-sand/60 p-3 text-sm">Hi Sushma, your 15% Goldstar birthday reward GS-2026 is ready for 02 Nov 2026. — Goldstar Banepa</div></div></Panel></div>{saved && <div className="mt-5 rounded-xl bg-white p-3 text-sm text-[#0E4C92]"><Check size={16} className="mr-2 inline" /> Your local form is saved; connected writes will use the loyalty_settings, tiers, wheel and templates tables.</div>}</PageFrame> }
function TierRow({ label, min, pct }: { label: string; min: string; pct: string }) { return <div className="flex items-center gap-3 rounded-xl border border-line p-3"><div className="flex-1"><p className="text-sm font-semibold">{label}</p><p className="text-xs text-graphite">From {formatCurrency(Number(min))}</p></div><Badge tone="gold">{pct}%</Badge><button className="text-graphite"><MoreHorizontal size={17} /></button></div> }
function WheelRow({ label, color, weight }: { label: string; color: string; weight: string }) { return <div className="flex items-center gap-3 text-sm"><span className="h-4 w-4 rounded-full border border-line" style={{ backgroundColor: color }} /><span className="flex-1">{label}</span><span className="text-xs text-graphite">{weight}% win probability</span></div> }

function StaffPage({ onToast }: { onToast: (state: ToastState) => void }) { const staff = useQuery({ queryKey: ['staff'], queryFn: async () => { if (!supabase) return []; const { data, error } = await supabase.from('staff_profiles').select('*').order('created_at'); if (error) throw error; return data || [] }, enabled: Boolean(supabase) }); return <PageFrame><SectionHeading eyebrow="Admin controls" title={pageInfo['/staff'][0]} description={pageInfo['/staff'][1]} action={<Button variant="secondary" onClick={() => onToast({ message: 'Add staff opens the create-staff Edge Function flow.', tone: 'success' })}><UserPlus size={17} /> Add staff</Button>} /><Panel title="Staff profiles">{staff.isLoading ? <SkeletonRows count={5} /> : staff.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.12em] text-graphite"><th className="pb-3">Name</th><th className="pb-3">Role</th><th className="pb-3">Status</th><th className="pb-3">Created</th><th /></tr></thead><tbody className="divide-y divide-line">{staff.data.map((member: any) => <tr key={member.id}><td className="py-4 font-semibold">{member.full_name}</td><td className="py-4"><Badge tone="neutral">{member.role}</Badge></td><td className="py-4"><Badge tone={member.is_active?'green':'red'}>{member.is_active?'Active':'Inactive'}</Badge></td><td className="py-4 text-sm text-graphite">{formatDate(member.created_at)}</td><td className="py-4 text-right"><button className="text-graphite"><MoreHorizontal size={17} /></button></td></tr>)}</tbody></table></div> : <EmptyState icon={Users} title="No staff profiles yet" description="The database will show staff profiles when an administrator creates them." />}</Panel></PageFrame> }
function AuditPage() { const audit = useQuery({ queryKey: ['audit'], queryFn: async () => { if (!supabase) return []; const { data, error } = await supabase.from('audit_log').select('*').order('created_at',{ascending:false}).limit(50); if (error) throw error; return data || [] }, enabled: Boolean(supabase) }); return <PageFrame><SectionHeading eyebrow="Admin controls" title={pageInfo['/audit-log'][0]} description={pageInfo['/audit-log'][1]} /><Panel title="Audit trail">{audit.isLoading ? <SkeletonRows count={6} /> : audit.data?.length ? <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead><tr className="border-b border-line text-[10px] uppercase tracking-[.12em] text-graphite"><th className="pb-3">When</th><th className="pb-3">Table</th><th className="pb-3">Action</th><th className="pb-3">Record</th><th className="pb-3">Diff</th></tr></thead><tbody className="divide-y divide-line">{audit.data.map((row: any) => <tr key={row.id}><td className="py-4 text-sm text-graphite">{formatDateTime(row.created_at)}</td><td className="py-4 font-mono text-xs">{row.table_name}</td><td className="py-4"><Badge tone="neutral">{row.action}</Badge></td><td className="py-4 font-mono text-xs text-graphite">{row.record_id || '—'}</td><td className="py-4"><button className="text-xs font-semibold underline">View JSON</button></td></tr>)}</tbody></table></div> : <EmptyState icon={ClipboardList} title="No audit entries yet" description="Changes made through the connected database will be recorded here." />}</Panel></PageFrame> }
function SetupPage() {
  const [running, setRunning] = useState(false);
  const [checks, setChecks] = useState<Array<{ label: string; detail: string; ok: boolean }>>([]);
  const runChecks = async () => {
    const client = supabase; if (!client) { setChecks([{ label: 'Connection', detail: 'Add Supabase URL and publishable key.', ok: false }]); return }
    setRunning(true);
    const next: Array<{ label: string; detail: string; ok: boolean }> = [{ label: 'Connection', detail: 'Supabase client is configured.', ok: true }];
    try {
      const { data: sessionData } = await client.auth.getSession();
      const signedIn = Boolean(sessionData.session);
      next.push({ label: 'Authentication', detail: signedIn ? 'Signed-in session found.' : 'No signed-in session found.', ok: signedIn });
      const tables = ['showrooms','staff_profiles','loyalty_settings','birthday_discount_tiers','loyalty_wheel_segments','customers','sales','sale_items','loyalty_ledger','loyalty_redemptions','birthday_coupons','message_templates','message_log','legacy_import_staging','audit_log'];
      const tableResults = await Promise.all(tables.map(async table => ({ table, result: await client.from(table).select('*', { head: true, count: 'exact' }).limit(1) })));
      const failed = tableResults.find(item => item.result.error);
      next.push({ label: 'Database contract', detail: failed ? `${failed.table}: ${failed.result.error?.message}` : `${tables.length} contract tables readable.`, ok: !failed });
      const { data: settings, error: settingsError } = await client.from('loyalty_settings').select('id').eq('id', 1).maybeSingle();
      next.push({ label: 'Loyalty settings', detail: settingsError ? settingsError.message : settings ? 'loyalty_settings id=1 exists.' : 'loyalty_settings id=1 is missing.', ok: Boolean(settings && !settingsError) });
      const counts = await Promise.all(['loyalty_wheel_segments','birthday_discount_tiers','message_templates'].map(async table => { const result = await client.from(table).select('id', { count: 'exact', head: true }); return { table, count: result.count || 0, error: result.error } }));
      const empty = counts.filter(item => item.count === 0);
      next.push({ label: 'Wheel / tiers / templates', detail: empty.length ? `Empty: ${empty.map(item => item.table).join(', ')}` : counts.map(item => `${item.table}: ${item.count}`).join(' · '), ok: empty.length === 0 });
    } catch (error) { next.push({ label: 'Health check error', detail: safeError(error), ok: false }) }
    setChecks(next); setRunning(false);
  };
  useEffect(() => { void runChecks() }, []);
  return <PageFrame><SectionHeading eyebrow="Admin controls" title={pageInfo['/setup'][0]} description={pageInfo['/setup'][1]} action={<Button variant="outline" loading={running} onClick={runChecks}><RefreshCw size={16} /> Run checks</Button>} /><Panel title="Pass / fail checklist">{checks.length ? <div className="divide-y divide-line">{checks.map(check => <div key={check.label} className="flex items-center gap-4 py-5"><div className={cls('grid h-10 w-10 place-items-center rounded-full', check.ok?'bg-white text-[#0E4C92]':'bg-gold/15 text-[#0E4C92]')}>{check.ok?<Check size={18}/>:<AlertCircle size={18}/>}</div><div className="flex-1"><p className="font-semibold">{check.label}</p><p className="mt-1 text-sm text-graphite">{check.detail}</p></div><Badge tone={check.ok?'green':'gold'}>{check.ok?'Pass':'Needs setup'}</Badge></div>)}</div> : <SkeletonRows count={4} />}<div className="mt-5 rounded-2xl bg-ink p-5 text-paper"><p className="text-sm font-semibold text-gold">Likely fixes</p><p className="mt-2 text-sm leading-6 text-white/60">If a table or RPC check fails, confirm the existing Supabase contract, deployment of Edge Functions, RLS permissions and the authenticated staff profile. Goldstar does not create schema automatically.</p></div></Panel></PageFrame>
}

export { App }
